INSERT OR REPLACE INTO einao_site_content (key, value_json, updated_at) VALUES ('site', '{"name":"Einao Solutions","tagline":"Technology that works around the realities of your organisation.","logo":"/assets/logos/Einao-Solutions-Logo-05.png","address":"Suite 12, Hilltop Plaza, No. 13, Wuse Zone 4, Abuja, Nigeria.","locations":["Abuja, Nigeria","Lagos, Nigeria"],"navigation":[{"label":"Home","href":"/"},{"label":"Capabilities","href":"/capabilities/","children":[{"label":"IT Consulting","href":"/capabilities/it-consulting/"},{"label":"Business Process Automation","href":"/capabilities/business-process-automation/"},{"label":"Enterprise Solutions & Digital Development","href":"/capabilities/enterprise-solutions/"}]},{"label":"Solutions","href":"/solutions/","children":[{"label":"PayX","href":"/solutions/payx/"},{"label":"Fylonn","href":"/solutions/fylonn/"},{"label":"IP PRO","href":"/solutions/ip-pro/"},{"label":"Custom Enterprise Systems","href":"/solutions/custom-enterprise-systems/"}]},{"label":"Industries","href":"/industries/","children":[{"label":"Government & Public Institutions","href":"/industries/government/"},{"label":"Businesses & Corporates","href":"/industries/business/"},{"label":"Regulatory & Service Organisations","href":"/industries/regulatory-services/"}]},{"label":"Insights","href":"/insights/"},{"label":"Our Work","href":"/work/","children":[{"label":"IPO Nigeria Case Study","href":"/work/ipo-nigeria-portal/"}]},{"label":"About","href":"/about/"}],"enquiryTypes":["IT Consulting","Process Automation","Enterprise Solution or Custom Development","PayX","Fylonn","System Integration","Other"],"footer":[{"title":"Explore","links":[{"label":"Work","href":"/work/"},{"label":"Insights","href":"/insights/"},{"label":"About","href":"/about/"},{"label":"Contact","href":"/contact/"}]},{"title":"Capabilities","links":[{"label":"IT Consulting","href":"/capabilities/it-consulting/"},{"label":"Business Process Automation","href":"/capabilities/business-process-automation/"},{"label":"Enterprise Solutions & Digital Development","href":"/capabilities/enterprise-solutions/"}]},{"title":"Solutions","links":[{"label":"PayX","href":"/solutions/payx/"},{"label":"Fylonn","href":"/solutions/fylonn/"},{"label":"IP PRO","href":"/solutions/ip-pro/"},{"label":"Custom Enterprise Systems","href":"/solutions/custom-enterprise-systems/"}]},{"title":"Industries","links":[{"label":"Government & Public Institutions","href":"/industries/government/"},{"label":"Businesses & Corporates","href":"/industries/business/"},{"label":"Regulatory & Service Organisations","href":"/industries/regulatory-services/"}]},{"title":"Legal","links":[{"label":"Privacy Notice","href":"/privacy-notice/"},{"label":"Terms of Use","href":"/terms-of-use/"}]}]}', datetime('now'));
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('home', 'Technology Consulting & Business Process Automation | Einao Solutions', 'Einao helps organisations improve operations through technology consulting, process automation, enterprise solutions, and custom digital systems.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (1, 'home', 'hero', 0, '{"eyebrow":"Technology shaped around your organisation","title":"We build the systems that keep organisations moving.","accent":"systems","body":["Einao helps organisations improve how they operate through technology consulting, business process automation, enterprise solutions, and custom digital development. We turn operational challenges into systems that work."],"cta":{"label":"Start a Conversation","href":"/contact/"},"secondaryCta":{"label":"Explore Our Capabilities","href":"/capabilities/"},"image":"/assets/images/placeholder-hero-poster.webp","video":"https://res.cloudinary.com/dqwfjxn8g/video/upload/v1793186378/6916389_Motion_Graphics_Motion_Graphic_1280x720_rcoiff.mp4","items":[{"title":"01 / Understand","body":""},{"title":"02 / Connect","body":""},{"title":"03 / Improve","body":""}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (2, 'home', 'feature', 1, '{"eyebrow":"01 / The operational reality","title":"When operations become complicated, the whole organisation feels it.","items":[{"title":"Slow approvals.","body":""},{"title":"Repetitive data entry.","body":""},{"title":"Disconnected applications.","body":""},{"title":"Unclear process ownership.","body":""},{"title":"Difficult-to-track transactions.","body":""},{"title":"Reports that take too long to prepare.","body":""}],"body":["Work that depends on follow-ups, spreadsheets, or institutional memory.","These are not isolated inconveniences. Over time, they affect service delivery, productivity, accountability, cost control, and an organisation''s ability to grow. Einao helps identify what is causing the friction and determine what needs to change."],"cta":{"label":"Talk Through an Operational Challenge","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (3, 'home', 'process', 2, '{"eyebrow":"02 / How we think","title":"Understand the operation before choosing the technology.","body":["Technology is not always the starting point. Sometimes a process needs to be redesigned. Sometimes existing systems need to communicate. Sometimes repetitive work should be automated. And sometimes the organisation needs a new digital system.","We begin by understanding the difference."],"items":[{"title":"Consult","body":"Analyse processes, clarify requirements, understand users and constraints, and establish a practical technology direction."},{"title":"Automate","body":"Improve workflows, reduce avoidable manual effort, structure approvals, and make information flow more effectively."},{"title":"Build","body":"Implement enterprise solutions, integrations, digital platforms, and custom software around the requirements."}],"cta":{"label":"Explore Our Capabilities","href":"/capabilities/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (4, 'home', 'feature', 3, '{"eyebrow":"Built around real operations","title":"Better systems begin with understanding.","body":["Processes, people and information all need to work together. We start with how your organisation operates, then shape the consulting, automation or digital system around what needs to improve."],"image":"/assets/images/placeholder-feature.webp","imageAlt":"Conceptual connected workflow, illustrated with green rings and nodes","cta":{"label":"Explore Our Capabilities","href":"/capabilities/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (5, 'home', 'services', 4, '{"eyebrow":"03 / Our capabilities","title":"Technology capabilities built around your operations.","items":[{"title":"IT Consulting","body":"Make technology decisions with a clear understanding of the problem. We help assess processes, define requirements, map workflows, and establish the right solution direction before implementation.","link":{"label":"Explore IT Consulting","href":"/capabilities/it-consulting/"}},{"title":"Business Process Automation","body":"Make workflows easier to manage. We identify bottlenecks, redesign repetitive activities, structure approvals, connect systems, and improve visibility across operational processes.","link":{"label":"Explore Process Automation","href":"/capabilities/business-process-automation/"}},{"title":"Enterprise Solutions & Digital Development","body":"Build systems around the way your organisation works-from enterprise applications and workflow systems to digital portals, integrations, and custom software.","link":{"label":"Explore Enterprise Solutions","href":"/capabilities/enterprise-solutions/"}}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (6, 'home', 'proof', 5, '{"eyebrow":"Selected institutional work","title":"Digital infrastructure must work beyond the launch.","body":["Einao has provided IT consulting support to the Federal Ministry of Industry, Trade and Investment''s Commercial Law Department since 2013. Einao built the IPO Nigeria portal and continues to support its maintenance, technical operation, optimisation, and upgrades.","The portal supports intellectual property application processes, including trademarks, patents, and industrial designs. It is an example of the operational demands involved in supporting a digital service used by applicants and institutional teams."],"cta":{"label":"Explore the IPO Nigeria Case Study","href":"/work/ipo-nigeria-portal/"},"items":[{"title":"IPO Nigeria","label":"Institutional digital service delivery","body":"Consulting. Portal development. Continued support."}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (7, 'home', 'solutions', 6, '{"eyebrow":"04 / Our solutions","title":"Digital solutions for real operational requirements.","body":["Einao''s solutions address practical needs such as payment visibility, structured workflows, information handling, and digital service delivery."],"items":[{"label":"Digital payments / 01","title":"PayX","body":"A digital payment solution for organisations seeking a more structured way to manage payment activity and maintain visibility over transactions. Coming soon — speak with us about your payment requirements.","link":{"label":"Explore PayX","href":"/solutions/payx/"},"badge":"Coming soon"},{"label":"Application & process management / 02","title":"Fylonn","body":"A modular application and processing management platform designed to help organisations digitise, coordinate and monitor applications, requests and operational processes from initiation to completion.","link":{"label":"Explore Fylonn","href":"/solutions/fylonn/"}},{"label":"IP management / 03","title":"IP PRO","body":"Intellectual property management software used in the IPO Nigeria portal engagement for institutional application and registry processes.","link":{"label":"Explore IP PRO","href":"/solutions/ip-pro/"}}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (8, 'home', 'industries', 7, '{"eyebrow":"05 / Who we work with","title":"Different organisations. Real operational needs.","items":[{"title":"Government & Public Institutions","body":"Digital systems for organisations managing complex processes, transactions, information, and public-facing services.","link":{"label":"Explore the industry","href":"/industries/government/"}},{"title":"Businesses & Corporates","body":"Technology that helps organisations structure operations, improve workflows, and connect systems as they grow.","link":{"label":"Explore the industry","href":"/industries/business/"}},{"title":"Regulatory & Service Organisations","body":"Digital processes designed around defined requirements, review stages, records, and service delivery.","link":{"label":"Explore the industry","href":"/industries/regulatory-services/"}}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (9, 'home', 'cards', 8, '{"eyebrow":"Where your change begins","title":"A clearer route from challenge to change.","items":[{"title":"IT Consulting","body":"Make technology decisions with a clear understanding of the problem. We help assess processes, define requirements, map workflows, and establish the right solution direction before implementation.","link":{"label":"Explore IT Consulting","href":"/capabilities/it-consulting/"},"image":"/assets/images/placeholder-card-1.webp"},{"title":"Business Process Automation","body":"Make workflows easier to manage. We identify bottlenecks, redesign repetitive activities, structure approvals, connect systems, and improve visibility across operational processes.","link":{"label":"Explore Process Automation","href":"/capabilities/business-process-automation/"},"image":"/assets/images/placeholder-card-2.webp"},{"title":"Enterprise Solutions & Digital Development","body":"Build systems around the way your organisation works-from enterprise applications and workflow systems to digital portals, integrations, and custom software.","link":{"label":"Explore Enterprise Solutions","href":"/capabilities/enterprise-solutions/"},"image":"/assets/images/placeholder-card-3.webp"},{"title":"Better questions. Better systems.","body":"Explore practical thinking about the operational decisions behind technology.","link":{"label":"Explore Insights","href":"/insights/"},"image":"/assets/images/placeholder-card-4.webp"}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (10, 'home', 'insights', 9, '{"eyebrow":"06 / Insights","title":"Better systems begin with better questions.","body":["Explore practical thinking on technology strategy, workflow automation, enterprise systems, and the operational decisions behind digital transformation."],"cta":{"label":"Explore Insights","href":"/insights/"}}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('about', 'About Einao Solutions | Enterprise Technology & Digital Transformation', 'Learn about Einao Solutions, an established technology company helping organisations improve operations through consulting, automation, and digital systems.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (11, 'about', 'hero', 0, '{"eyebrow":"About Einao","title":"Technology should work around the organisation-not the other way around.","body":["Einao Solutions Limited helps organisations understand operational challenges and respond with practical technology. Our work connects consulting, process improvement, automation, and digital solution delivery."],"cta":{"label":"Start a Conversation","href":"/contact/"},"leadership":{"id":"collins-nkwoji","name":"Collins Nkwoji","role":"CEO","credentials":"MBA, CPA, FCA, FCIT","bio":"","image":"/assets/images/founder.webp","imageAlt":"Collins Nkwoji, CEO of Einao Solutions"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (12, 'about', 'editorial', 1, '{"title":"Our perspective","body":["Digital transformation is not simply the act of moving a process online. If the underlying process is unclear, fragmented, or unnecessarily complicated, digitising it can preserve the same problems in a new format.","We look at how work moves through an organisation: how information is captured, where decisions happen, how teams coordinate, which systems are involved, and what makes delivery difficult. That understanding shapes the solution.","Sometimes the right intervention is process redesign. Sometimes it is automation or integration. Sometimes a new system is required. The aim is to make technology serve a defined operational need."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (13, 'about', 'editorial', 2, '{"title":"Our history","body":["Founded in 2011, Einao Solutions has developed its work around technology consulting and digital solutions for organisational needs. Its engagement with the Federal Ministry of Industry, Trade and Investment''s Commercial Law Department dates to 2013 and includes work on the IPO Nigeria portal, alongside ongoing technical support and system improvement."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (14, 'about', 'approach', 3, '{"title":"How we work","items":[{"title":"Understand before building","body":"We clarify the problem, users, process, constraints, and intended outcomes before deciding on the technology."},{"title":"Solve the actual problem","body":"We distinguish between a process problem, an integration problem, an automation opportunity, and a requirement for a new system."},{"title":"Design for the operating environment","body":"Solutions must make sense for the people, workflows, information, and practical conditions in which they will be used."},{"title":"Treat implementation as part of the work","body":"Technology creates value when it is implemented in a way that supports real use, with maintenance and improvement addressed where they form part of the engagement."}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (15, 'about', 'editorial', 4, '{"title":"Our mission and vision","body":["We design and implement digital solutions that simplify operations, improve processes, and help organisations work more effectively.","To become a foremost IT solutions provider that empowers organisations to operate smarter, faster, and more efficiently through digital solutions."]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('capabilities', 'Technology Consulting, Process Automation & Digital Solutions | Einao', 'Explore Einao''s IT consulting, business process automation, enterprise solutions, system integration, and custom digital development capabilities.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (16, 'capabilities', 'hero', 0, '{"eyebrow":"Our capabilities","title":"The right technology starts with the right understanding.","body":["Einao works across the path from operational diagnosis to digital implementation. We help organisations define the problem, improve the process, and deliver the systems required to support better ways of working."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (17, 'capabilities', 'services', 1, '{"title":"From understanding to implementation.","items":[{"title":"IT Consulting","body":"Make technology decisions with a clear understanding of the problem. We help assess processes, define requirements, map workflows, and establish the right solution direction before implementation.","link":{"label":"Explore IT Consulting","href":"/capabilities/it-consulting/"}},{"title":"Business Process Automation","body":"Make workflows easier to manage. We identify bottlenecks, redesign repetitive activities, structure approvals, connect systems, and improve visibility across operational processes.","link":{"label":"Explore Process Automation","href":"/capabilities/business-process-automation/"}},{"title":"Enterprise Solutions & Digital Development","body":"Build systems around the way your organisation works-from enterprise applications and workflow systems to digital portals, integrations, and custom software.","link":{"label":"Explore Enterprise Solutions","href":"/capabilities/enterprise-solutions/"}}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('capabilities/it-consulting', 'IT Consulting & Technology Strategy | Einao Solutions', 'Define requirements, assess business processes, evaluate technology options, and plan digital initiatives with Einao''s IT consulting services.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (18, 'capabilities/it-consulting', 'hero', 0, '{"eyebrow":"IT Consulting","title":"Make technology decisions with the problem clearly defined.","body":["Technology projects can become expensive and difficult to deliver when requirements are unclear, workflows are poorly understood, or tools are selected before the organisation knows what it needs. Einao helps teams establish a clearer view of the operational problem and the technology response it calls for."],"cta":{"label":"Discuss a Consulting Requirement","href":"/contact/?enquiry=IT%20Consulting"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (19, 'capabilities/it-consulting', 'editorial', 1, '{"title":"What we help clarify","body":[],"items":[{"title":"Business and process analysis","body":"Understand how work is performed today, who is involved, what information is required, and where delays, duplication, or uncertainty occur."},{"title":"Requirements definition","body":"Translate stakeholder needs into a clearer description of the functions, workflows, users, data, and constraints a solution must address."},{"title":"Process mapping","body":"Make the current workflow visible, including hand-offs, approvals, decision points, exceptions, and dependencies."},{"title":"Technology and solution assessment","body":"Evaluate the problem before selecting an approach, considering whether process redesign, automation, integration, configuration, or custom development is appropriate."},{"title":"Solution architecture and planning","body":"Define the major components, relationships, dependencies, and implementation considerations needed to move from requirement to delivery."}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (20, 'capabilities/it-consulting', 'approach', 2, '{"title":"A practical engagement.","items":[{"title":"Understand","body":"Establish the business context, users, existing systems, constraints, and desired outcome."},{"title":"Analyse","body":"Review processes, requirements, information flows, and the causes of the current difficulty."},{"title":"Define","body":"Document the problem, priorities, solution options, and relevant implementation considerations."},{"title":"Plan","body":"Set out the proposed scope, dependencies, delivery priorities, and next steps."}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (21, 'capabilities/it-consulting', 'editorial', 3, '{"title":"Common questions","body":[],"items":[{"title":"When should an organisation start with consulting?","body":"Start when the operational problem, requirements, or solution direction is not yet clear enough to make a confident technology decision."},{"title":"What does the consulting work include?","body":"The work can include process analysis, requirements definition, workflow mapping, technology assessment, and solution planning, depending on the agreed scope."},{"title":"Does consulting lead to implementation?","body":"It can. The findings can inform a later implementation with Einao or provide a clearer basis for another delivery approach."},{"title":"Can you review our existing systems and tools?","body":"Yes. Existing applications, information flows, dependencies, and constraints can be considered as part of the assessment before a solution direction is recommended."},{"title":"What do we need before starting?","body":"A clear description of the operational difficulty and the people or process affected is a useful starting point. The detail can then be developed during the engagement."},{"title":"How is the consulting scope agreed?","body":"The scope is shaped around the questions the organisation needs answered, the processes or systems to be reviewed, and the practical next step required."}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('capabilities/business-process-automation', 'Business Process Automation & Workflow Solutions | Einao Solutions', 'Improve workflows with process redesign, digital approvals, workflow automation, system integration, and operational reporting tailored to your organisation.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (22, 'capabilities/business-process-automation', 'hero', 0, '{"eyebrow":"Business Process Automation","title":"Make the workflow work better.","body":["As organisations grow, manual processes and informal workarounds become harder to manage. Approvals get delayed, information is entered repeatedly, reports depend on manual compilation, and teams struggle to see the status of work across departments.","Einao helps organisations analyse, redesign, and automate appropriate workflows so work can move through clearer steps, with better information flow and visibility."],"cta":{"label":"Identify a Workflow to Improve","href":"/contact/?enquiry=Process%20Automation"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (23, 'capabilities/business-process-automation', 'editorial', 1, '{"title":"What can be improved","body":[],"items":[{"title":"Process optimisation","body":"Identify unnecessary steps, duplicated effort, avoidable hand-offs, and unclear responsibilities before deciding what to automate."},{"title":"Workflow automation","body":"Structure recurring activities, task assignments, notifications, and process stages so work follows a defined sequence rather than relying entirely on manual follow-up."},{"title":"Digital approvals and escalations","body":"Define routes for review, approval, rejection, and escalation, with status visibility and traceability appropriate to the process."},{"title":"System integration","body":"Connect relevant applications and services so information can move between systems with less repeated entry and fewer manual transfers."},{"title":"Automated reporting and visibility","body":"Reduce the effort required to compile routine operational information and support more consistent views of process activity."}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (24, 'capabilities/business-process-automation', 'editorial', 2, '{"title":"How we approach automation","body":["We assess the current process, define the intended outcome, identify what should change, design the workflow, and determine the appropriate combination of automation, integration, and supporting technology. The objective is not to automate every step; it is to improve the operation."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (25, 'capabilities/business-process-automation', 'editorial', 3, '{"title":"Common questions","body":[],"items":[{"title":"What processes are suitable for automation?","body":"Processes with repeated steps, clear rules, recurring approvals, avoidable hand-offs, or frequent manual reporting are often useful starting points."},{"title":"Will automation replace existing systems?","body":"Not necessarily. The appropriate response may be process redesign, workflow automation, integration, configuration, or a combination of approaches."},{"title":"How do we choose where to start?","body":"Start with a process where delays, duplication, limited visibility, or manual effort create a clear operational cost and where improvement can be measured."},{"title":"Can automation support approvals and escalations?","body":"Yes. Appropriate workflows can define review, approval, rejection, escalation, notifications, and status visibility around the organisation''s rules."},{"title":"Can automation connect different applications?","body":"System integration can be considered where the relevant applications, interfaces, data flows, and technical constraints support a reliable connection."},{"title":"How do you avoid automating a broken process?","body":"The current process is assessed first so unnecessary steps, duplicated effort, unclear ownership, and avoidable hand-offs can be addressed before automation is designed."}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('capabilities/enterprise-solutions', 'Enterprise Solutions & Custom Software Development | Einao Solutions', 'Einao designs enterprise applications, digital portals, workflow systems, integrations, and custom software around organisational requirements.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (26, 'capabilities/enterprise-solutions', 'hero', 0, '{"eyebrow":"Enterprise Solutions & Digital Development","title":"Build the digital systems your organisation actually needs.","body":["Not every operational requirement can be met by a generic application. Organisations may need systems that reflect specific workflows, service models, information structures, approval rules, user groups, and integration needs. Einao designs and implements digital solutions around those requirements."],"cta":{"label":"Discuss a Digital Solution","href":"/contact/?enquiry=Enterprise%20Solution%20or%20Custom%20Development"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (27, 'capabilities/enterprise-solutions', 'editorial', 1, '{"title":"What we deliver","body":[],"items":[{"title":"Enterprise applications and workflow systems","body":"Support structured processes such as task assignment, review, assessment, approval, case handling, and status tracking, with capabilities defined by the requirements of the engagement."},{"title":"Digital portals and service platforms","body":"Create digital access points through which users can submit requests, provide information, upload documents, make payments where required, and follow the progress of a service."},{"title":"Custom software and business applications","body":"Design software around a defined operational requirement when available tools do not adequately support the intended workflow."},{"title":"Document and information workflows","body":"Organise the handling, review, retrieval, and movement of documents and information across relevant processes."},{"title":"System integration","body":"Connect new and existing applications, services, and data flows where technically feasible and within the agreed scope."},{"title":"Implementation and ongoing improvement","body":"Support deployment and subsequent maintenance or improvement where included in the engagement."}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (28, 'capabilities/enterprise-solutions', 'editorial', 2, '{"title":"Designed around requirements","body":["Every engagement begins with a clear understanding of users, processes, data, system dependencies, operating conditions, and the outcome the organisation needs. This shapes the scope and informs the design and implementation approach."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (29, 'capabilities/enterprise-solutions', 'editorial', 3, '{"title":"Common questions","body":[],"items":[{"title":"When is a custom enterprise solution appropriate?","body":"It may be appropriate when available tools do not support the organisation''s required workflows, information structures, user groups, or integration needs."},{"title":"Can you integrate existing systems?","body":"Integration can be considered where the systems, interfaces, data flows, and technical constraints make it feasible within the agreed scope."},{"title":"What happens after launch?","body":"Support, maintenance, and improvement can be included where agreed, with the post-launch approach shaped around the system and organisation."},{"title":"What information is considered during design?","body":"The work considers users, workflows, data, permissions, system dependencies, operating conditions, integrations, and the outcome the organisation needs."},{"title":"Can a portal include documents, payments, or service requests?","body":"Where required by the agreed scope, a digital portal can support information submission, document upload, payments, and service progress tracking."},{"title":"How do you decide between configuration and custom development?","body":"The choice depends on the requirements, existing systems, process needs, integration options, constraints, and the most practical route to the intended outcome."}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('solutions', 'Enterprise Solutions & Digital Systems | Einao Solutions', 'Explore Einao''s digital solutions and enterprise systems for payment processes, organisational workflows, and specific operational requirements.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (30, 'solutions', 'hero', 0, '{"eyebrow":"Our solutions","title":"Digital solutions for specific operational needs.","body":["Einao''s product portfolio addresses different requirements, from payment operations to institutional intellectual property management and application processing. Explore each product or contact us to discuss its current capabilities and suitability."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (31, 'solutions', 'solutions', 1, '{"title":"Start with the requirement.","items":[{"label":"Digital payments / 01","title":"PayX","body":"A digital payment solution for organisations seeking a more structured way to manage payment activity and maintain visibility over transactions. Coming soon — speak with us about your payment requirements.","link":{"label":"Explore PayX","href":"/solutions/payx/"},"badge":"Coming soon"},{"label":"Application & process management / 02","title":"Fylonn","body":"A modular application and processing management platform designed to help organisations digitise, coordinate and monitor applications, requests and operational processes from initiation to completion.","link":{"label":"Explore Fylonn","href":"/solutions/fylonn/"}},{"label":"IP management / 03","title":"IP PRO","body":"Intellectual property management software used in the IPO Nigeria portal engagement for institutional application and registry processes.","link":{"label":"Explore IP PRO","href":"/solutions/ip-pro/"}}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (32, 'solutions', 'editorial', 2, '{"title":"Custom enterprise solutions","body":["When a requirement needs a tailored approach, Einao can assess the operating model and define an appropriate digital solution, integration, or development scope."]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('solutions/custom-enterprise-systems', 'Custom Enterprise Systems & Digital Solutions | Einao Solutions', 'Discuss a custom enterprise system, digital portal, workflow, integration, or business application shaped around your organisation''s requirements.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (33, 'solutions/custom-enterprise-systems', 'hero', 0, '{"eyebrow":"Custom enterprise systems","title":"Build the digital system your operating environment requires.","body":["Some requirements need a solution shaped around a specific operating model. Einao helps define the users, workflows, information, integrations, and practical constraints before designing an appropriate digital system."],"cta":{"label":"Discuss a Digital Solution","href":"/contact/?enquiry=Enterprise%20Solution%20or%20Custom%20Development"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (34, 'solutions/custom-enterprise-systems', 'editorial', 1, '{"title":"Designed around the requirement","body":["We can support enterprise applications, digital portals, workflow systems, information and document flows, integrations, and custom software where those capabilities are appropriate to the agreed scope."]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('solutions/payx', 'PayX Digital Payment Solution | Einao Solutions', 'Discuss PayX with Einao to explore a more structured approach to digital payment collection, transaction visibility, and payment reporting.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (35, 'solutions/payx', 'hero', 0, '{"eyebrow":"PayX","title":"Bring greater structure to payment operations.","body":["PayX is a digital payment solution for organisations seeking a more structured way to manage payment activity and maintain visibility over transactions.","PayX is currently in final development. Speak with the Einao team to discuss your payment requirements and we will be in touch when the product is available for your organisation."],"cta":{"label":"Enquire About PayX","href":"/contact/?enquiry=PayX"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (36, 'solutions/payx', 'editorial', 1, '{"title":"Coming soon","body":["PayX is not yet available for general implementation. We are working to confirm its supported payment channels, transaction tracking, reconciliation, reporting, and integration capabilities before release.","Tell us how your organisation collects payments, where visibility becomes difficult, and what your teams need to manage more effectively. We will use that conversation to determine fit and keep you updated on availability."]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('solutions/fylonn', 'Fylonn Application & Process Management | Einao Solutions', 'Contact Einao to learn about Fylonn and discuss whether its verified capabilities fit your organisation''s workflow requirements.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (37, 'solutions/fylonn', 'hero', 0, '{"eyebrow":"Fylonn","title":"Manage Applications. Connect Processes. Improve Service Delivery.","body":["Fylonn is a modular application and processing management platform designed to help organisations digitise, coordinate and monitor applications, requests and operational processes from initiation to completion.","Bring application intake, internal processing, communication and operational oversight into a connected environment built around the way your organisation works."],"cta":{"label":"Discuss Your Requirements","href":"/contact/?enquiry=Fylonn"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (38, 'solutions/fylonn', 'editorial', 1, '{"title":"From receiving requests to managing the entire process","body":["Fylonn is designed to support the journey from the moment a request is submitted to the point at which it is processed, communicated, and monitored.","Rather than treating each stage as an isolated activity, the platform brings related functions together so organisations can work towards more coordinated and visible service delivery."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (39, 'solutions/fylonn', 'editorial', 2, '{"title":"Five connected modules","body":[],"items":[{"title":"Fylonn Connect","body":"Application and request intake. Provides the customer-facing entry point for applications, submissions, service requests, and supporting information."},{"title":"Fylonn Flow","body":"Back-office processing. Supports the internal handling of applications and requests as they move through operational workflows."},{"title":"Fylonn Publish","body":"Publication and journal management. Supports publication-related activities and the organisation of records, directories, and journal-oriented processes."},{"title":"Fylonn Assist","body":"Customer support and case management. Supports the management and resolution of enquiries, support requests, and related cases."},{"title":"Fylonn Insight","body":"Operational performance and intelligence. Provides a foundation for monitoring operational activity and presenting performance information to support oversight and decision-making."}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (40, 'solutions/fylonn', 'editorial', 3, '{"title":"Who Fylonn is for","body":[],"items":[{"title":"Government and Public Institutions","body":"Support the management of formal applications and institutional processes through structured workflows and improved visibility. Potential applications include registrations, renewals, licences, permits, regulatory applications, and formal requests."},{"title":"Private Businesses and Service Providers","body":"Coordinate recurring business processes, reduce manual follow-ups and improve visibility into customer-facing and internal operations. Potential applications include onboarding, service requests, internal approvals, document verification, and administrative workflows."}]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (41, 'solutions/fylonn', 'editorial', 4, '{"title":"Common questions","body":[],"items":[{"title":"What is Fylonn?","body":"Fylonn is a modular application and processing management platform being developed by Einao Solutions. It is intended to help organisations digitise, coordinate, manage and monitor applications, requests and structured operational processes."},{"title":"Who is Fylonn designed for?","body":"Fylonn is intended for government institutions, regulatory bodies, service providers and private businesses that manage structured applications, requests or operational cases."},{"title":"Is Fylonn available for implementation?","body":"Fylonn is being developed progressively. Product readiness and implementation availability should be confirmed with Einao Solutions."},{"title":"Can organisations use individual modules?","body":"The product is being designed around modular adoption. The ability to deploy each module independently will depend on its technical dependencies and the final product architecture."}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('solutions/ip-pro', 'IP PRO Intellectual Property Management | Einao Solutions', 'Explore IP PRO, a structured digital solution for intellectual property application and records management.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (42, 'solutions/ip-pro', 'hero', 0, '{"eyebrow":"IP PRO","title":"Manage intellectual property work with greater clarity.","body":["IP PRO is designed to support structured intellectual property applications, records, review stages, and institutional visibility from submission through decision."],"cta":{"label":"Discuss IP PRO","href":"/contact/?enquiry=IP%20PRO"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (43, 'solutions/ip-pro', 'editorial', 1, '{"title":"A clearer path through intellectual property work","body":["Bring application intake, records, review stages, and communication into a more visible operating process shaped around the requirements of your institution."]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('industries', 'Technology Solutions for Government, Business & Institutions | Einao', 'Explore how Einao''s technology consulting, automation, and digital solution capabilities can support government, business, regulatory, and service organisations.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (44, 'industries', 'hero', 0, '{"eyebrow":"Who we work with","title":"Technology shaped around the realities of your organisation.","body":["Different organisations face different operating conditions. The common requirement is technology that responds to real workflows, users, information needs, and service expectations. Einao starts with those realities before defining the right approach."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (45, 'industries', 'industries', 1, '{"title":"Different organisations. Real operational needs.","items":[{"title":"Government & Public Institutions","body":"Digital systems for organisations managing complex processes, transactions, information, and public-facing services.","link":{"label":"Explore the industry","href":"/industries/government/"}},{"title":"Businesses & Corporates","body":"Technology that helps organisations structure operations, improve workflows, and connect systems as they grow.","link":{"label":"Explore the industry","href":"/industries/business/"}},{"title":"Regulatory & Service Organisations","body":"Digital processes designed around defined requirements, review stages, records, and service delivery.","link":{"label":"Explore the industry","href":"/industries/regulatory-services/"}}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('industries/government', 'Technology for Government & Public Institutions | Einao', 'Explore institutional workflows, digital services and Einao''s IPO Nigeria portal experience.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (46, 'industries/government', 'hero', 0, '{"eyebrow":"Government & Public Institutions","title":"Digital services shaped around institutional work.","body":["Public institutions may manage applications, approvals, records, payments, and services that involve multiple stakeholders and defined processes. Einao''s work in institutional digital systems includes the IPO Nigeria portal engagement. We help define operational requirements and deliver or support digital systems according to the scope of each engagement."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (47, 'industries/government', 'proof', 1, '{"eyebrow":"Selected institutional work","title":"Digital infrastructure must work beyond the launch.","body":["Einao has provided IT consulting support to the Federal Ministry of Industry, Trade and Investment''s Commercial Law Department since 2013. Einao built the IPO Nigeria portal and continues to support its maintenance, technical operation, optimisation, and upgrades.","The portal supports intellectual property application processes, including trademarks, patents, and industrial designs. It is an example of the operational demands involved in supporting a digital service used by applicants and institutional teams."],"cta":{"label":"Explore the IPO Nigeria Case Study","href":"/work/ipo-nigeria-portal/"},"items":[{"title":"IPO Nigeria","label":"Institutional digital service delivery","body":"Consulting. Portal development. Continued support."}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('industries/business', 'Technology for Businesses & Corporates | Einao', 'Improve operational structure, workflows and connections between business systems.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (48, 'industries/business', 'hero', 0, '{"eyebrow":"Businesses & Corporates","title":"Build structure around the way your business works.","body":["As businesses grow, processes can become fragmented across teams, spreadsheets, and disconnected applications. Einao helps organisations assess their operations, improve workflows, connect systems, and define digital solutions that support their business requirements."],"cta":{"label":"Discuss a Business Requirement","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (49, 'industries/business', 'services', 1, '{"title":"Support the next stage of your operations.","items":[{"title":"IT Consulting","body":"Make technology decisions with a clear understanding of the problem. We help assess processes, define requirements, map workflows, and establish the right solution direction before implementation.","link":{"label":"Explore IT Consulting","href":"/capabilities/it-consulting/"}},{"title":"Business Process Automation","body":"Make workflows easier to manage. We identify bottlenecks, redesign repetitive activities, structure approvals, connect systems, and improve visibility across operational processes.","link":{"label":"Explore Process Automation","href":"/capabilities/business-process-automation/"}}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('industries/regulatory-services', 'Technology for Regulatory & Service Organisations | Einao', 'Define clearer information flows for structured reviews, requests, records and service processes.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (50, 'industries/regulatory-services', 'hero', 0, '{"eyebrow":"Regulatory & Service Organisations","title":"Clearer processes for structured service delivery.","body":["Organisations responsible for structured reviews, requests, applications, records, and service processes need clear information flows and dependable digital workflows. Einao can help assess those requirements and determine an appropriate automation, integration, or development approach."],"cta":{"label":"Discuss Your Service Process","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (51, 'industries/regulatory-services', 'services', 1, '{"title":"Connect requirements to delivery.","items":[{"title":"Business Process Automation","body":"Make workflows easier to manage. We identify bottlenecks, redesign repetitive activities, structure approvals, connect systems, and improve visibility across operational processes.","link":{"label":"Explore Process Automation","href":"/capabilities/business-process-automation/"}},{"title":"Enterprise Solutions & Digital Development","body":"Build systems around the way your organisation works-from enterprise applications and workflow systems to digital portals, integrations, and custom software.","link":{"label":"Explore Enterprise Solutions","href":"/capabilities/enterprise-solutions/"}}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('work', 'Digital Transformation Projects & Case Studies | Einao Solutions', 'Explore selected work involving institutional digital platforms, technology consulting, process improvement, and enterprise solutions delivered or supported by Einao.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (52, 'work', 'hero', 0, '{"eyebrow":"Selected work","title":"The work behind systems people rely on.","body":["Our case studies explain the context, the operational challenge, Einao''s role, and the work involved."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (53, 'work', 'proof', 1, '{"eyebrow":"Selected institutional work","title":"Digital infrastructure must work beyond the launch.","body":["Einao has provided IT consulting support to the Federal Ministry of Industry, Trade and Investment''s Commercial Law Department since 2013. Einao built the IPO Nigeria portal and continues to support its maintenance, technical operation, optimisation, and upgrades.","The portal supports intellectual property application processes, including trademarks, patents, and industrial designs. It is an example of the operational demands involved in supporting a digital service used by applicants and institutional teams."],"cta":{"label":"Explore the IPO Nigeria Case Study","href":"/work/ipo-nigeria-portal/"},"items":[{"title":"IPO Nigeria","label":"Institutional digital service delivery","body":"Consulting. Portal development. Continued support."}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('work/ipo-nigeria-portal', 'IPO Nigeria Portal Case Study | Einao Solutions', 'Read about Einao''s work building and supporting the IPO Nigeria portal for the Federal Ministry of Industry, Trade and Investment''s Commercial Law Department.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (54, 'work/ipo-nigeria-portal', 'hero', 0, '{"eyebrow":"Selected institutional work","title":"Supporting the digital processes behind intellectual property services.","body":["Einao''s engagement with the Federal Ministry of Industry, Trade and Investment''s Commercial Law Department dates to 2013. Einao built the IPO Nigeria portal and continues to support its technical operation, maintenance, optimisation, and upgrades."],"cta":{"label":"Discuss an Institutional Digital Requirement","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (55, 'work/ipo-nigeria-portal', 'editorial', 1, '{"title":"The operational context","body":["Digital services for intellectual property applications must support structured information submission and processing. The IPO Nigeria portal supports application processes relating to trademarks, patents, and industrial designs."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (56, 'work/ipo-nigeria-portal', 'editorial', 2, '{"title":"Einao''s role","body":["Einao''s role includes building the portal and continuing to support it through maintenance, technical support, optimisation, and upgrades."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (57, 'work/ipo-nigeria-portal', 'editorial', 3, '{"title":"Why ongoing support matters","body":["A digital platform is not finished in operational terms simply because it has been launched. Systems need continued technical attention as requirements evolve, users interact with the service, and improvements become necessary. Ongoing support helps maintain the platform and address agreed technical needs."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (58, 'work/ipo-nigeria-portal', 'services', 4, '{"title":"Related capabilities","items":[{"title":"IT Consulting","body":"Make technology decisions with a clear understanding of the problem. We help assess processes, define requirements, map workflows, and establish the right solution direction before implementation.","link":{"label":"Explore IT Consulting","href":"/capabilities/it-consulting/"}},{"title":"Enterprise Solutions & Digital Development","body":"Build systems around the way your organisation works-from enterprise applications and workflow systems to digital portals, integrations, and custom software.","link":{"label":"Explore Enterprise Solutions","href":"/capabilities/enterprise-solutions/"}}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('insights', 'Insights on Technology, Automation & Operations | Einao Solutions', 'Practical perspectives on technology strategy, business process automation, enterprise systems, and digital transformation from Einao Solutions.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (59, 'insights', 'hero', 0, '{"eyebrow":"Insights","title":"Better systems begin with better questions.","body":["Ideas and practical perspectives on the operational decisions behind technology: how to define requirements, improve workflows, connect systems, and approach digital transformation with clarity."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (60, 'insights', 'insights', 1, '{"title":"Practical perspectives on better operations.","body":["Our thinking starts with the operating reality behind the brief. Explore the questions that help organisations choose, connect, and improve technology with purpose."],"items":[{"title":"Before you buy software: five questions every organisation should answer","body":"A clearer definition of the problem creates better technology decisions and more useful outcomes.","label":"Technology strategy","image":"/assets/images/Graphite monitor with enterprise dashboard.png","link":{"label":"Discuss this perspective","href":"/contact/"}},{"title":"Digitising a broken process does not fix it","body":"The strongest automation work begins by understanding where the process creates friction for people and the organisation.","label":"Process improvement","image":"/assets/images/Hands sketching a business workflow.png","link":{"label":"Discuss this perspective","href":"/contact/"}},{"title":"Where manual work creates hidden operational costs","body":"Repeated handoffs, spreadsheets, and follow-ups quietly shape the cost and reliability of everyday service delivery.","label":"Operations","image":"/assets/images/Hands mapping a streamlined workflow.png","link":{"label":"Discuss this perspective","href":"/contact/"}},{"title":"Integrate existing systems or replace them?","body":"A practical comparison of the signals that point toward integration, replacement, or a more deliberate combination of both.","label":"Enterprise systems","image":"/assets/images/Nigerian IT Consultants Reviewing a Laptop.png","link":{"label":"Discuss this perspective","href":"/contact/"}}]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('contact', 'Contact Einao Solutions | Discuss Your Technology Requirements', 'Contact Einao Solutions to discuss IT consulting, business process automation, enterprise systems, integrations, or a custom digital solution.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (61, 'contact', 'hero', 0, '{"eyebrow":"Start a conversation","title":"Tell us what your organisation needs to do better.","body":["Whether you are improving an existing process, planning a digital platform, considering automation, or trying to connect systems, start by telling us what is happening. We will use the conversation to understand the requirement and identify an appropriate next step."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('privacy-notice', 'Privacy Notice | Einao Solutions', 'How Einao Solutions uses and protects information submitted through this website.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (62, 'privacy-notice', 'hero', 0, '{"eyebrow":"Privacy notice","title":"Your information should be handled with care.","body":["This notice explains how Einao Solutions uses information provided through this website and contact forms."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (63, 'privacy-notice', 'editorial', 1, '{"title":"Information we receive","body":["We may receive your name, work email, organisation, role, phone number, enquiry type, and the details you choose to include in your message."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (64, 'privacy-notice', 'editorial', 2, '{"title":"How we use it","body":["We use submitted information to understand and respond to enquiries, route requirements to the appropriate team, and maintain a record of conversations where necessary to support the relationship."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (65, 'privacy-notice', 'editorial', 3, '{"title":"Your choices","body":["You may ask us what information we hold about you or request that we correct or remove it, subject to applicable legal and operational requirements. Contact hello@einaosolutions.com for privacy questions."]}', 1);
INSERT OR REPLACE INTO einao_pages (slug, title, description, status, updated_at) VALUES ('terms-of-use', 'Terms of Use | Einao Solutions', 'Terms governing use of the Einao Solutions website and its published content.', 'published', datetime('now'));
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (66, 'terms-of-use', 'hero', 0, '{"eyebrow":"Terms of use","title":"Use this site as a source of information about Einao.","body":["These terms describe the general conditions for using the Einao Solutions website."],"cta":{"label":"Start a Conversation","href":"/contact/"}}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (67, 'terms-of-use', 'editorial', 1, '{"title":"Website content","body":["The website provides general information about Einao Solutions, its capabilities, solutions, and experience. Content does not constitute a proposal, guarantee, or professional advice for a specific engagement."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (68, 'terms-of-use', 'editorial', 2, '{"title":"Accuracy and availability","body":["We aim to keep the website accurate and available, but information may change as services, products, and requirements develop. Confirm scope, capabilities, and commercial terms with Einao before relying on them for a decision."]}', 1);
INSERT OR REPLACE INTO page_blocks (id, page_slug, block_type, position, config, visible) VALUES (69, 'terms-of-use', 'editorial', 3, '{"title":"Contact","body":["Questions about these terms can be sent to hello@einaosolutions.com."]}', 1);